if c.source_order_marker > b.source_order_marker:
    classification = FORWARD_REFERENCE
else if c.source_order_marker < b.source_order_marker:
    classification = RETROGRADE_REFERENCE
else:
    classification = INDETERMINATE

eap-tprp-evidence = { profile_version: "eap-tprp-1", evidence_id: bounded-id, subject_digest: sha256-id, source_order_domain: bounded-id, source_event_id: bounded-id, source_order_marker: source-marker, source_principal: bounded-id, source_assertion_digest: sha256-id, source_authentication_ref: sha256-id, receiver_id: bounded-id, receipt_sequence: receipt-sequence, receiver_assertion_digest: sha256-id, receiver_authentication_ref: sha256-id, baseline_evidence_digest: sha256-id / null, classification: reference-classification, provenance_commitment: sha256-id, evidence_refs: digest-set, * tstr => any, }
reference-classification = "FORWARD_REFERENCE" / "RETROGRADE_REFERENCE" / "INDETERMINATE"
sha256-id = tstr .regexp "^sha256:[0-9a-f]{64}$" source-marker = 0..9007199254740991 receipt-sequence = 1..9007199254740991 bounded-id = tstr digest-set = [*128 sha256-id]
